#!/usr/bin/env python3
"""Scan Claude session JSONL for secret-like values; print masked evidence only."""
import glob
import json
import os
import re
import sys
from collections import Counter

ROOT = r"C:\Users\Administrator\.claude\projects\E--erp-agent--"

PATTERNS = {
    "github_pat": re.compile(r"github_pat_[A-Za-z0-9_]{10,}"),
    "mongo_uri": re.compile(r"mongodb(?:\+srv)?://[^\s\"'<>\\]+"),
    "api_key_assign": re.compile(
        r"\b(DEEPSEEK|TYPESAFE|OPENAI|ANTHROPIC|VOLC|ARK)_API_KEY\s*[=:]\s*[\"']?([^\s\"',;}]+)"
    ),
    "password_assign": re.compile(
        r"(?i)\b(password|passwd|pwd|mongo_password)\s*[=:]\s*[\"']?([^\s\"',;}]+)"
    ),
    "secret_assign": re.compile(
        r"(?i)\b(secret|token|api_key|apikey)\s*[=:]\s*[\"']?([^\s\"',;}]+)"
    ),
    "bearer": re.compile(r"Bearer\s+([A-Za-z0-9._~+/=-]{20,})"),
}


def mask_value(name, value):
    v = value.strip().strip("\"'")
    if v.startswith("$") or "getenv" in v or "get_env" in v or v.lower() in {"none", "null", "changeme", "xxx", "***", "<redacted>"}:
        return f"<reference:{v[:60]}>"
    if v in {"...", "******", "********"} or set(v) <= {"*", "."}:
        return "<placeholder>"
    return f"{v[:4]}*** (len={len(v)})"


def mask_mongo(uri):
    scheme, sep, rest = uri.partition("://")
    has_cred = "@" in rest
    tail = rest.rsplit("@", 1)[-1]
    host = tail.split("/", 1)[0]
    # Show only host prefix length/type, not full host or credentials.
    suffix = "mongodb.net" if "mongodb.net" in host else ("localhost" if "localhost" in host or "127.0.0.1" in host else "other-host")
    return f"{scheme}://{'<user>:<pass>@' if has_cred else ''}<{suffix}>/... (len={len(uri)})"


counts = Counter()
for path in sorted(glob.glob(os.path.join(ROOT, "*.jsonl"))):
    name = os.path.basename(path)[:8]
    with open(path, "r", encoding="utf-8", errors="replace") as f:
        for lineno, line in enumerate(f, 1):
            for kind, pat in PATTERNS.items():
                for m in pat.finditer(line):
                    counts[(name, kind)] += 1
                    if counts[(name, kind)] > 6:
                        continue
                    if kind == "github_pat":
                        raw = m.group(0)
                        shown = raw[:8] + "***" + f" (len={len(raw)})"
                    elif kind == "mongo_uri":
                        shown = mask_mongo(m.group(0))
                    elif kind == "bearer":
                        shown = mask_value("bearer", m.group(1))
                    else:
                        shown = f"{m.group(1)}={mask_value(m.group(1), m.group(2))}"
                    print(f"{name}:{lineno} [{kind}] {shown}")

print("\n=== counts by file/kind ===")
for (name, kind), n in sorted(counts.items()):
    print(f"{name} {kind}: {n}")

