#!/usr/bin/env python3
"""Extract non-content metadata for session JSONL files."""
import glob
import json
import os

ROOT = r"C:\Users\Administrator\.claude\projects\E--erp-agent--"
OUT = r"C:\Users\Administrator\AppData\Local\Temp\claude_session_meta.txt"

with open(OUT, "w", encoding="utf-8") as out:
    for path in sorted(glob.glob(os.path.join(ROOT, "*.jsonl"))):
        sid = os.path.basename(path)[:-6]
        size = os.path.getsize(path)
        counts = {}
        roles = {}
        first_ts = last_ts = None
        cwd = None
        summaries = []
        first_user = None
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            for line in f:
                try:
                    obj = json.loads(line)
                except Exception:
                    continue
                if not isinstance(obj, dict):
                    continue
                t = obj.get("type", "?")
                counts[t] = counts.get(t, 0) + 1
                msg = obj.get("message")
                if isinstance(msg, dict):
                    role = msg.get("role", "?")
                    roles[role] = roles.get(role, 0) + 1
                    if role == "user" and first_user is None:
                        content = msg.get("content")
                        if isinstance(content, str):
                            first_user = content
                        elif isinstance(content, list):
                            for b in content:
                                if isinstance(b, dict) and b.get("type") == "text":
                                    first_user = str(b.get("text", ""))
                                    break
                ts = obj.get("timestamp")
                if ts:
                    first_ts = first_ts or ts
                    last_ts = ts
                cwd = cwd or obj.get("cwd")
                if t == "summary" and obj.get("summary"):
                    summaries.append(str(obj["summary"])[:120])
        out.write(f"\n=== {sid} ===\n")
        out.write(f"size={size} first={first_ts} last={last_ts} cwd={cwd}\n")
        out.write(f"types={counts}\nroles={roles}\n")
        out.write(f"summaries={summaries}\n")
        if first_user:
